Database Schema:
CREATE TABLE `city` (
  `id` INTEGER,
  `city_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `games` (
  `id` INTEGER,
  `games_year` INTEGER,
  `games_name` TEXT,
  `season` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `games_city` (
  `games_id` INTEGER REFERENCES `games`(`id`),
  `city_id` INTEGER REFERENCES `city`(`id`)
);

CREATE TABLE `medal` (
  `id` INTEGER,
  `medal_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `noc_region` (
  `id` INTEGER,
  `noc` TEXT,
  `region_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `person` (
  `id` INTEGER,
  `full_name` TEXT,
  `gender` TEXT,
  `height` INTEGER,
  `weight` INTEGER,
  PRIMARY KEY (`id`)
);

CREATE TABLE `games_competitor` (
  `id` INTEGER,
  `games_id` INTEGER REFERENCES `games`(`id`),
  `person_id` INTEGER REFERENCES `person`(`id`),
  `age` INTEGER,
  PRIMARY KEY (`id`)
);

CREATE TABLE `person_region` (
  `person_id` INTEGER REFERENCES `person`(`id`),
