Database Schema:
CREATE TABLE `ATT_CLASSES` (
  `ATT_CLASS_ID` INTEGER,
  `ATT_CLASS` TEXT,
  PRIMARY KEY (`ATT_CLASS_ID`)
);

CREATE TABLE `OBJ_CLASSES` (
  `OBJ_CLASS_ID` INTEGER,
  `OBJ_CLASS` TEXT,
  PRIMARY KEY (`OBJ_CLASS_ID`)
);

CREATE TABLE `IMG_OBJ` (
  `IMG_ID` INTEGER,
  `OBJ_SAMPLE_ID` INTEGER,
  `OBJ_CLASS_ID` INTEGER REFERENCES `OBJ_CLASSES`(`OBJ_CLASS_ID`),
  `X` INTEGER,
  `Y` INTEGER,
  `W` INTEGER,
  `H` INTEGER,
  PRIMARY KEY (`IMG_ID`, `OBJ_SAMPLE_ID`)
);

CREATE TABLE `IMG_OBJ_ATT` (
  `IMG_ID` INTEGER REFERENCES `IMG_OBJ`(`IMG_ID`),
  `ATT_CLASS_ID` INTEGER REFERENCES `ATT_CLASSES`(`ATT_CLASS_ID`),
  `OBJ_SAMPLE_ID` INTEGER REFERENCES `IMG_OBJ`(`OBJ_SAMPLE_ID`),
  PRIMARY KEY (`IMG_ID`, `ATT_CLASS_ID`, `OBJ_SAMPLE_ID`)
);

CREATE TABLE `PRED_CLASSES` (
  `PRED_CLASS_ID` INTEGER,
  `PRED_CLASS` TEXT,
  PRIMARY KEY (`PRED_CLASS_ID`)
);

CREATE TABLE `IMG_REL` (
  `IMG_ID` INTEGER REFERENCES `IMG_OBJ`(`IMG_ID`),
  `PRED_CLASS_ID` INTEGER REFERENCES `PRED_CLASSES`(`PRED_CLASS_ID`),
  `OBJ1_SAMPLE_ID` INTEGER REFERENCES `IMG_OBJ`(`OBJ_SAMPLE_ID`),
  `OBJ2_SAMPLE_ID` INTEGER REFERENCES `IMG_OBJ`(`OBJ_SAMPLE_ID`),
  PRIMARY KEY (`IMG_ID`, `PRED_CLASS_ID`, `OBJ1_SAMPLE_ID`, `OBJ2_SAMPLE_ID`)
);

